sys_variable_value.value:
(function execute(inputs, outputs) {
    var gr = new GlideRecord("sys_import_set_run");
    gr.addQuery("set.table_name", "=", inputs.import_set_table_name);
    gr.addQuery("sys_created_on", ">=", inputs.run_start);
    gr.addQuery("state", 'running');
    gr.setLimit(1);
    gr.query();
    outputs.transform_is_running = gr.next();
})(inputs, outputs);

